// Generated from the editable example files. Run npm run examples:sync after changing them.
export const vpsServersHtml = "<good-main-view title=\"Servers\" description=\"Manage virtual servers in this local GoodUI case study.\" eyebrow=\"Case studies · VPS hoster\">\n  <div good-main-view-actions>\n    <good-action-group>\n      <good-button variant=\"outline\" size=\"small\" [icon]=\"filterIcon\" (click)=\"filterOpen.set(true)\">Filter</good-button>\n      <good-button size=\"small\" [icon]=\"addIcon\" (click)=\"addServer()\">Add server</good-button>\n    </good-action-group>\n  </div>\n  <good-section>\n    <good-expandable label=\"Important status updates · 4 maintenance notices · 1 warning\" icon=\"chevron\">\n      <good-alert tone=\"warning\" title=\"Regional maintenance\" message=\"This is sample status content for the case study. No live service status is queried.\" />\n    </good-expandable>\n  </good-section>\n  <good-section>\n    <good-tabs ariaLabel=\"Infrastructure sections\">\n      <good-tab value=\"servers\" label=\"Servers\" [badge]=\"store.count()\">\n        @if (selectedIds().length) {\n          <good-action-group ariaLabel=\"Selected server actions\">\n            <good-paragraph>{{ selectedIds().length }} selected</good-paragraph>\n            <good-button variant=\"outline\" size=\"small\" (click)=\"setSelectedStatus('running')\">Start selected</good-button>\n            <good-button variant=\"outline\" size=\"small\" (click)=\"setSelectedStatus('stopped')\">Stop selected</good-button>\n            <good-button variant=\"destructive\" size=\"small\" (click)=\"bulkDeleteOpen.set(true)\">Delete selected</good-button>\n          </good-action-group>\n        }\n        <good-table label=\"Virtual servers\" tableStyle=\"compact\" [data]=\"visibleServers()\" [columns]=\"columns\"\n          [getRowId]=\"rowId\" [searchable]=\"true\" searchPlaceholder=\"Search servers\"\n          selectable [(selectedRowId)]=\"selectedServerId\" (rowSelected)=\"view($event)\"\n          emptyMessage=\"No servers match these filters.\" />\n        @if (selectedServer(); as server) {\n          <good-group [title]=\"server.name\" [headingLevel]=\"3\" appearance=\"contrast\">\n            <good-prose>\n              <good-paragraph>{{ server.plan }} · {{ server.architecture }} · {{ server.image }} · {{ server.location }} ({{ server.zone }})</good-paragraph>\n              <good-paragraph>Public IP: {{ server.publicIp }} · Status: {{ server.status }} · Created: {{ server.created }}</good-paragraph>\n              <good-paragraph>Labels: {{ server.labels.length ? server.labels.join(', ') : 'None' }}</good-paragraph>\n              <good-paragraph>Networking: {{ server.ipv4 ? 'IPv4 ' : '' }}{{ server.ipv6 ? 'IPv6 ' : '' }}{{ server.privateNetwork || '' }}</good-paragraph>\n              <good-paragraph>SSH keys: {{ server.sshKeys.length ? server.sshKeys.join(', ') : 'None' }}</good-paragraph>\n              <good-paragraph>Volume: {{ server.volume ? server.volume.name + ' · ' + server.volume.sizeGb + ' GB' : 'None' }}</good-paragraph>\n              <good-paragraph>Firewall: {{ server.firewall || 'None' }} · Backups: {{ server.backups ? 'On' : 'Off' }} · Placement: {{ server.placement || 'None' }}</good-paragraph>\n              @if (server.cloudConfig) { <good-paragraph>Cloud-init configuration supplied for this demo.</good-paragraph> }\n            </good-prose>\n          </good-group>\n        }\n      </good-tab>\n      <good-tab value=\"snapshots\" label=\"Snapshots\"><good-group title=\"Snapshots\" appearance=\"plain\"><good-paragraph>No snapshots have been created in this local demo.</good-paragraph></good-group></good-tab>\n      <good-tab value=\"backups\" label=\"Backups\"><good-group title=\"Backups\" appearance=\"plain\"><good-paragraph>Backups can be enabled while configuring a server.</good-paragraph></good-group></good-tab>\n      <good-tab value=\"placement\" label=\"Placement groups\"><good-group title=\"Placement groups\" appearance=\"plain\"><good-paragraph>No placement groups are available in this local demo.</good-paragraph></good-group></good-tab>\n    </good-tabs>\n  </good-section>\n  <good-section>\n    <good-prose>\n      @if (store.notice()) { <good-paragraph role=\"status\">{{ store.notice() }}</good-paragraph> }\n      @if (feedback()) { <good-paragraph role=\"status\">{{ feedback() }}</good-paragraph> }\n      <good-paragraph>This case study keeps data in memory and uses documentation IP addresses. It does not provision infrastructure.</good-paragraph>\n      <good-button variant=\"ghost\" size=\"small\" (click)=\"sourceOpen.set(true)\">View source</good-button>\n    </good-prose>\n  </good-section>\n</good-main-view>\n\n<good-modal [(open)]=\"filterOpen\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"Filter servers\" description=\"Combine fields to narrow the server list.\" />\n  <good-group title=\"Search and attributes\" appearance=\"plain\">\n    <good-input label=\"Name or IP address\" [showLabel]=\"true\" placeholder=\"Search by name or IP\" [(value)]=\"nameFilter\" />\n    <good-select label=\"Network zone\" [showLabel]=\"true\" [options]=\"zoneOptions\" placeholder=\"Any zone\" [(value)]=\"zoneFilter\" />\n    <good-select label=\"Location\" [showLabel]=\"true\" [options]=\"locationOptions\" placeholder=\"Any location\" [(value)]=\"locationFilter\" />\n    <good-select label=\"Type\" [showLabel]=\"true\" [options]=\"planOptions\" placeholder=\"Any type\" [(value)]=\"planFilter\" />\n    <good-select label=\"Status\" [showLabel]=\"true\" [options]=\"statusOptions\" placeholder=\"Any status\" [(value)]=\"statusFilter\" />\n    <good-input label=\"Label\" [showLabel]=\"true\" placeholder=\"Filter labels\" [(value)]=\"labelFilter\" />\n  </good-group>\n  <good-modal-footer>\n    <good-action-group>\n      <good-button variant=\"outline\" (click)=\"clearFilters()\">Clear filters</good-button>\n      <good-button (click)=\"filterOpen.set(false)\">Show {{ visibleServers().length }} servers</good-button>\n    </good-action-group>\n  </good-modal-footer>\n</good-modal>\n\n<good-modal [(open)]=\"bulkDeleteOpen\" size=\"small\">\n  <good-modal-header title=\"Delete selected servers\" description=\"This removes only local demo records.\" />\n  <good-paragraph>Delete {{ selectedIds().length }} selected servers?</good-paragraph>\n  <good-modal-footer>\n    <good-action-group>\n      <good-button variant=\"outline\" (click)=\"bulkDeleteOpen.set(false)\">Cancel</good-button>\n      <good-button variant=\"destructive\" (click)=\"deleteSelected()\">Delete selected</good-button>\n    </good-action-group>\n  </good-modal-footer>\n</good-modal>\n\n<good-modal [(open)]=\"deleteOpen\" size=\"small\">\n  <good-modal-header title=\"Delete server\" description=\"This only removes the server from the local case study.\" />\n  <good-paragraph>Delete {{ pendingDelete()?.name }}?</good-paragraph>\n  <good-modal-footer>\n    <good-action-group>\n      <good-button variant=\"outline\" (click)=\"deleteOpen.set(false)\">Cancel</good-button>\n      <good-button variant=\"destructive\" (click)=\"deleteServer()\">Delete</good-button>\n    </good-action-group>\n  </good-modal-footer>\n</good-modal>\n\n<good-modal [(open)]=\"sourceOpen\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"VPS server list source\" />\n  <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"servers-page.html\" />\n  <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"servers-page.ts\" />\n  <good-code-block [code]=\"storeSource\" language=\"typescript\" title=\"vps-store.ts\" />\n</good-modal>\n";
export const vpsServersTs = "import { ChangeDetectionStrategy, Component, Signal, computed, inject, input, signal } from '@angular/core';\nimport { Router } from '@angular/router';\nimport {\n  GoodActionGroupComponent, GoodAlertComponent, GoodBadgeComponent, GoodButtonComponent, GoodCheckboxComponent, GoodDropdownComponent, GoodExpandableComponent,\n  GoodCodeBlockComponent, GoodGroupComponent, GoodInputComponent, GoodMainViewComponent,\n  GoodModalComponent, GoodModalFooterComponent, GoodModalHeaderComponent, GoodParagraphComponent,\n  GoodProseComponent, GoodSectionComponent, GoodSelectComponent, GoodTableColumn, GoodTableComponent, GoodTabsComponent,\n  GoodTabComponent, GoodSelectOption, flexRenderComponent, LucideEllipsis, LucideFilter, LucidePlus,\n} from '@goodui/angular';\nimport { VpsCaseStudyStore, VpsServer } from './vps-store';\nimport { vpsServersHtml, vpsServersTs, vpsStoreTs } from './source-code.generated';\n\n@Component({\n  selector: 'example-vps-select-row-cell',\n  standalone: true,\n  imports: [GoodCheckboxComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `<good-checkbox [label]=\"'Select ' + server().name\" [checked]=\"selectedIds()().includes(server().id)\"\n    (checkedChange)=\"onToggle()(server().id, $event)\" />`,\n})\nclass VpsSelectRowCellComponent {\n  readonly server = input.required<VpsServer>();\n  readonly selectedIds = input.required<Signal<readonly string[]>>();\n  readonly onToggle = input.required<(id: string, checked: boolean) => void>();\n}\n\n@Component({\n  selector: 'example-vps-select-all-cell',\n  standalone: true,\n  imports: [GoodCheckboxComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `<good-checkbox label=\"Select all visible servers\" [checked]=\"allVisible()()\"\n    (checkedChange)=\"onToggle()($event)\" />`,\n})\nclass VpsSelectAllCellComponent {\n  readonly allVisible = input.required<Signal<boolean>>();\n  readonly onToggle = input.required<(checked: boolean) => void>();\n}\n\n@Component({\n  selector: 'example-vps-actions-cell',\n  standalone: true,\n  imports: [GoodDropdownComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `<good-dropdown [ariaLabel]=\"'Actions for ' + server().name\" menuLabel=\"Server actions\"\n    [icon]=\"menuIcon\" [iconOnly]=\"true\" [showChevron]=\"false\" [items]=\"items()\" placement=\"bottom-start\" />`,\n})\nclass VpsActionsCellComponent {\n  readonly menuIcon = LucideEllipsis;\n  readonly server = input.required<VpsServer>();\n  readonly onView = input.required<(server: VpsServer) => void>();\n  readonly onStatus = input.required<(server: VpsServer) => void>();\n  readonly onDelete = input.required<(server: VpsServer) => void>();\n  readonly items = computed(() => [\n    { id: 'view', label: 'View details', action: () => this.onView()(this.server()) },\n    { id: 'status', label: this.server().status === 'running' ? 'Stop server' : 'Start server', action: () => this.onStatus()(this.server()) },\n    { id: 'delete', label: 'Delete server', action: () => this.onDelete()(this.server()) },\n  ]);\n}\n\n@Component({\n  selector: 'example-vps-servers-page',\n  standalone: true,\n  imports: [GoodActionGroupComponent, GoodAlertComponent, GoodButtonComponent, GoodCodeBlockComponent, GoodExpandableComponent, GoodGroupComponent,\n    GoodInputComponent, GoodMainViewComponent, GoodModalComponent, GoodModalFooterComponent,\n    GoodModalHeaderComponent, GoodParagraphComponent, GoodProseComponent, GoodSelectComponent,\n    GoodSectionComponent, GoodTableComponent, GoodTabsComponent, GoodTabComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './servers-page.html',\n})\nexport class VpsServersPageComponent {\n  private readonly router = inject(Router);\n  readonly store = inject(VpsCaseStudyStore);\n  readonly filterIcon = LucideFilter;\n  readonly addIcon = LucidePlus;\n  readonly filterOpen = signal(false);\n  readonly sourceOpen = signal(false);\n  readonly deleteOpen = signal(false);\n  readonly pendingDelete = signal<VpsServer | null>(null);\n  readonly selectedServerId = signal<string | null>(null);\n  readonly nameFilter = signal('');\n  readonly zoneFilter = signal<string | null>(null);\n  readonly locationFilter = signal<string | null>(null);\n  readonly planFilter = signal<string | null>(null);\n  readonly statusFilter = signal<string | null>(null);\n  readonly labelFilter = signal('');\n  readonly feedback = signal('');\n  readonly selectedIds = signal<readonly string[]>([]);\n  readonly bulkDeleteOpen = signal(false);\n  readonly zoneOptions: readonly GoodSelectOption[] = [\n    { value: 'eu-central', label: 'Europe Central' }, { value: 'ap-southeast', label: 'Asia Pacific' },\n    { value: 'us-west', label: 'US West' }, { value: 'us-east', label: 'US East' },\n  ];\n  readonly locationOptions: readonly GoodSelectOption[] = [\n    { value: 'Nuremberg', label: 'Nuremberg' }, { value: 'Falkenstein', label: 'Falkenstein' },\n    { value: 'Helsinki', label: 'Helsinki' }, { value: 'Singapore', label: 'Singapore' },\n    { value: 'Ashburn', label: 'Ashburn' }, { value: 'Hillsboro', label: 'Hillsboro' },\n  ];\n  readonly planOptions: readonly GoodSelectOption[] = [\n    { value: 'CPX22', label: 'CPX22' }, { value: 'CPX32', label: 'CPX32' },\n    { value: 'CPX42', label: 'CPX42' }, { value: 'CPX52', label: 'CPX52' },\n    { value: 'CPX62', label: 'CPX62' }, { value: 'CX22', label: 'CX22' },\n    { value: 'CX32', label: 'CX32' }, { value: 'CCX23', label: 'CCX23' }, { value: 'CCX33', label: 'CCX33' },\n  ];\n  readonly statusOptions: readonly GoodSelectOption[] = [\n    { value: 'running', label: 'Running' }, { value: 'stopped', label: 'Stopped' },\n  ];\n  readonly visibleServers = computed(() => this.store.servers().filter(server => {\n    const query = this.nameFilter().trim().toLowerCase();\n    const label = this.labelFilter().trim().toLowerCase();\n    return (!query || `${server.name} ${server.publicIp}`.toLowerCase().includes(query))\n      && (!label || server.labels.some(value => value.toLowerCase().includes(label)))\n      && (!this.zoneFilter() || server.zone === this.zoneFilter())\n      && (!this.locationFilter() || server.location === this.locationFilter())\n      && (!this.planFilter() || server.plan === this.planFilter())\n      && (!this.statusFilter() || server.status === this.statusFilter());\n  }));\n  readonly allVisible = computed(() => this.visibleServers().length > 0\n    && this.visibleServers().every(server => this.selectedIds().includes(server.id)));\n  readonly selectedServer = computed(() => this.store.servers().find(server => server.id === this.selectedServerId()) ?? null);\n  readonly columns: GoodTableColumn<VpsServer>[] = [\n    { id: 'select', header: () => flexRenderComponent(VpsSelectAllCellComponent, { inputs: {\n        allVisible: this.allVisible, onToggle: (checked: boolean) => this.toggleAllVisible(checked),\n      } }), accessorFn: server => server.id, enableGlobalFilter: false,\n      cell: context => flexRenderComponent(VpsSelectRowCellComponent, { key: context.row.original.id, inputs: {\n        server: context.row.original, selectedIds: this.selectedIds,\n        onToggle: (id: string, checked: boolean) => this.toggleSelected(id, checked),\n      } }) },\n    { accessorKey: 'name', header: 'Name', enableSorting: true },\n    { accessorKey: 'publicIp', header: 'Public IP', meta: { noWrap: true } },\n    { accessorKey: 'location', header: 'Location', enableSorting: true },\n    { accessorKey: 'created', header: 'Created', enableSorting: true, meta: { noWrap: true } },\n    { accessorKey: 'status', header: 'Status', enableSorting: true,\n      cell: context => flexRenderComponent(GoodBadgeComponent, { inputs: {\n        label: context.row.original.status === 'running' ? 'Running' : 'Stopped',\n        color: context.row.original.status === 'running' ? 'success' : 'secondary', variant: 'light', size: 'small',\n      } }) },\n    { id: 'actions', header: 'Actions', meta: { align: 'end', noWrap: true }, enableGlobalFilter: false,\n      cell: context => flexRenderComponent(VpsActionsCellComponent, { key: context.row.original.id, inputs: {\n        server: context.row.original,\n        onView: (server: VpsServer) => this.view(server),\n        onStatus: (server: VpsServer) => this.toggleStatus(server),\n        onDelete: (server: VpsServer) => this.confirmDelete(server),\n      } }) },\n  ];\n  readonly rowId = (server: VpsServer): string => server.id;\n  readonly htmlSource = vpsServersHtml;\n  readonly typescriptSource = vpsServersTs;\n  readonly storeSource = vpsStoreTs;\n\n  addServer(): void { void this.router.navigateByUrl('/examples/case-studies/vpshoster/create'); }\n  view(server: VpsServer): void { this.selectedServerId.set(server.id); }\n  toggleSelected(id: string, checked: boolean): void {\n    this.selectedIds.update(ids => checked ? [...new Set([...ids, id])] : ids.filter(value => value !== id));\n  }\n  toggleAllVisible(checked: boolean): void {\n    const visible = new Set(this.visibleServers().map(server => server.id));\n    this.selectedIds.update(ids => checked ? [...new Set([...ids, ...visible])]\n      : ids.filter(id => !visible.has(id)));\n  }\n  setSelectedStatus(status: VpsServer['status']): void {\n    for (const id of this.selectedIds()) this.store.setStatus(id, status);\n    this.feedback.set(`${this.selectedIds().length} servers are now ${status}.`);\n  }\n  deleteSelected(): void {\n    const count = this.selectedIds().length;\n    for (const id of this.selectedIds()) this.store.remove(id);\n    if (this.selectedServerId() && this.selectedIds().includes(this.selectedServerId()!)) this.selectedServerId.set(null);\n    this.selectedIds.set([]);\n    this.bulkDeleteOpen.set(false);\n    this.feedback.set(`${count} servers were removed from this local demo.`);\n  }\n  toggleStatus(server: VpsServer): void {\n    const status = server.status === 'running' ? 'stopped' : 'running';\n    this.store.setStatus(server.id, status);\n    this.feedback.set(`${server.name} is now ${status}.`);\n  }\n  confirmDelete(server: VpsServer): void { this.pendingDelete.set(server); this.deleteOpen.set(true); }\n  deleteServer(): void {\n    const server = this.pendingDelete();\n    if (!server) return;\n    this.store.remove(server.id);\n    this.selectedIds.update(ids => ids.filter(id => id !== server.id));\n    if (this.selectedServerId() === server.id) this.selectedServerId.set(null);\n    this.feedback.set(`${server.name} was removed from this local demo.`);\n    this.pendingDelete.set(null);\n    this.deleteOpen.set(false);\n  }\n  clearFilters(): void {\n    this.nameFilter.set(''); this.zoneFilter.set(null); this.locationFilter.set(null);\n    this.planFilter.set(null); this.statusFilter.set(null); this.labelFilter.set('');\n  }\n}\n";
export const vpsCreateHtml = "<good-main-view layout=\"fill\">\n  <good-expandable goodMainViewToolbar label=\"Important status updates · 4 maintenance notices · 1 warning\" icon=\"chevron\">\n    <good-alert tone=\"warning\" title=\"Regional maintenance\" message=\"This is sample status content for the case study. No live service status is queried.\" />\n  </good-expandable>\n  <good-assistant-panel label=\"Order summary\" [(open)]=\"summaryOpen\">\n    <good-assistant-main>\n      <good-section>\n        <good-prose>\n          <good-link route=\"/examples/case-studies/vpshoster/servers\">← Back to servers</good-link>\n          <good-heading [level]=\"1\">Create servers</good-heading>\n          <good-paragraph>Choose a plan and configure the server. This case study previews the workflow locally; Create adds demo records without provisioning infrastructure.</good-paragraph>\n        </good-prose>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"1. Server type\" appearance=\"plain\">\n          <good-paragraph>Select a shared or dedicated plan. The selected row sets CPU, memory, storage, and base price.</good-paragraph>\n          <good-tabs ariaLabel=\"Server plan families\" (tabActivated)=\"selectFamily($event.id)\">\n            <good-tab value=\"shared\" label=\"Shared resources\">\n              <good-radio-group label=\"Shared resource class\" [options]=\"planCategories\" orientation=\"horizontal\"\n                [value]=\"planCategory()\" (valueChange)=\"selectCategory($event)\" />\n              @if (planCategory() === 'cost') {\n                <good-radio-group label=\"Architecture\" [options]=\"architectureOptions\" orientation=\"horizontal\"\n                  [(value)]=\"architecture\" />\n              }\n              <good-table label=\"Shared resource plans\" tableStyle=\"compact\" [data]=\"sharedPlans()\" [columns]=\"planColumns\"\n                [getRowId]=\"planRowId\" [reorderable]=\"false\" selectable [(selectedRowId)]=\"planId\" />\n            </good-tab>\n            <good-tab value=\"dedicated\" label=\"Dedicated resources\">\n              <good-paragraph>General purpose plans provide dedicated virtual CPUs for sustained workloads.</good-paragraph>\n              <good-table label=\"Dedicated resource plans\" tableStyle=\"compact\" [data]=\"dedicatedPlans\" [columns]=\"planColumns\"\n                [getRowId]=\"planRowId\" [reorderable]=\"false\" selectable [(selectedRowId)]=\"planId\" />\n            </good-tab>\n          </good-tabs>\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"2. Location\" appearance=\"plain\">\n          <good-paragraph>Location affects network availability and may change the monthly price.</good-paragraph>\n          <good-select label=\"Server location\" [showLabel]=\"true\" [options]=\"locations\" [(value)]=\"location\" />\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"3. Image\" appearance=\"plain\">\n          <good-paragraph>Choose an operating system or a ready-to-use application image, then select its version.</good-paragraph>\n          <good-tabs ariaLabel=\"Image families\" (tabActivated)=\"selectImageFamily($event.id)\">\n            <good-tab value=\"os\" label=\"OS images\">\n              <good-select label=\"Operating system\" [showLabel]=\"true\" [options]=\"osImages\"\n                [value]=\"image()\" (valueChange)=\"setImage($event)\" />\n            </good-tab>\n            <good-tab value=\"apps\" label=\"Apps\">\n              <good-select label=\"Application image\" [showLabel]=\"true\" [options]=\"appImages\"\n                [value]=\"image()\" (valueChange)=\"setImage($event)\" />\n            </good-tab>\n          </good-tabs>\n          <good-select label=\"Image version\" [showLabel]=\"true\" [options]=\"versionOptions()\" [(value)]=\"imageVersion\" />\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"4. Networking\" appearance=\"plain\">\n          <good-paragraph>Keep at least one public address or a private network. IPv4 adds €0.50 per server each month; IPv6 is included.</good-paragraph>\n          <good-group appearance=\"plain\" spacing=\"tight\">\n            <good-checkbox label=\"Public IPv4\" [showLabel]=\"true\" [(checked)]=\"ipv4\" />\n            <good-checkbox label=\"Public IPv6\" [showLabel]=\"true\" [(checked)]=\"ipv6\" />\n            <good-checkbox label=\"Private network\" [showLabel]=\"true\" [(checked)]=\"privateNetwork\" />\n          </good-group>\n          @if (privateNetwork()) {\n            <good-select label=\"Private network\" [showLabel]=\"true\" [options]=\"privateNetworkOptions()\"\n              placeholder=\"Choose a network\" [(value)]=\"privateNetworkId\" />\n          }\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"5. SSH keys\" appearance=\"plain\">\n          <good-paragraph>Select the public keys to install. Without a key, this demo still lets you create a server but shows a security reminder.</good-paragraph>\n          <good-listbox label=\"SSH keys\" [items]=\"sshKeys()\" selectionMode=\"multiple\" appearance=\"checkbox\"\n            [(selectedIds)]=\"selectedKeyIds\" [bordered]=\"false\" compact />\n          <good-button variant=\"outline\" size=\"small\" (click)=\"keyModalOpen.set(true)\">Add SSH key</good-button>\n          @if (!selectedKeyIds().length) {\n            <good-alert tone=\"warning\" title=\"No SSH key selected\" message=\"Choose or add a public key for key-based access.\" />\n          }\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"6. Volumes\" appearance=\"plain\">\n          <good-paragraph>Attach an optional SSD volume at the same location. This demo estimates €0.05 per GB each month.</good-paragraph>\n          @if (!volumeEnabled()) {\n            <good-button variant=\"outline\" (click)=\"volumeEnabled.set(true)\">Add volume</good-button>\n          } @else {\n            <good-form-row [columns]=\"2\">\n              <good-input label=\"Volume name\" [showLabel]=\"true\" [(value)]=\"volumeName\" />\n              <good-number-input label=\"Volume size in GB\" [showLabel]=\"true\" [min]=\"10\" [max]=\"10000\" [step]=\"10\" [(value)]=\"volumeSize\" />\n            </good-form-row>\n            <good-button variant=\"outline\" size=\"small\" (click)=\"volumeEnabled.set(false)\">Remove volume</good-button>\n          }\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"7. Firewall and backups\" appearance=\"plain\">\n          <good-select label=\"Firewall\" [showLabel]=\"true\" [options]=\"firewallOptions\"\n            placeholder=\"No firewall\" [(value)]=\"firewall\" />\n          <good-checkbox label=\"Enable daily backups (+20% of plan price)\" [showLabel]=\"true\" [(checked)]=\"backups\" />\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"8. Placement and labels\" appearance=\"plain\">\n          <good-select label=\"Placement group\" [showLabel]=\"true\" [options]=\"placementOptions\"\n            placeholder=\"No placement group\" [(value)]=\"placement\" />\n          <good-input label=\"Labels\" [showLabel]=\"true\" placeholder=\"production, api\" [(value)]=\"labels\" />\n          <good-paragraph>Separate labels with commas. They become searchable in the server list.</good-paragraph>\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"9. Cloud config\" appearance=\"plain\">\n          <good-paragraph>Optional cloud-init user data is limited to 32 KiB. It is kept only while this page is open.</good-paragraph>\n          <good-textarea label=\"Cloud-init configuration\" [showLabel]=\"true\" [rows]=\"5\"\n            placeholder=\"#cloud-config\" [(value)]=\"cloudConfig\" />\n        </good-group>\n      </good-section>\n\n      <good-section>\n        <good-group title=\"10. Server names\" appearance=\"plain\">\n          <good-paragraph>Give every server a distinct lowercase name. The suggestions follow your image, plan, and location.</good-paragraph>\n          @for (index of nameIndexes(); track index) {\n            <good-input [label]=\"'Server ' + (index + 1) + ' name'\" [showLabel]=\"true\" [required]=\"true\"\n              [value]=\"nameFor(index)\" (valueChange)=\"setName(index, $event)\" />\n          }\n        </good-group>\n      </good-section>\n    </good-assistant-main>\n\n    <good-assistant-header><good-subheading [level]=\"2\">Order summary</good-subheading></good-assistant-header>\n    <good-assistant-body>\n        <good-prose>\n          <good-paragraph><strong>{{ selectedPlan().name }}</strong> · {{ selectedPlan().vcpus }} vCPUs · {{ selectedPlan().memoryGb }} GB RAM · {{ selectedPlan().diskGb }} GB SSD · {{ selectedPlan().category === 'cost' ? architecture() : 'x86' }}</good-paragraph>\n          <good-paragraph><strong>Location:</strong> {{ location() }} · {{ zone() }}</good-paragraph>\n          <good-paragraph><strong>Image:</strong> {{ imageLabel() }}</good-paragraph>\n          <good-paragraph><strong>Network:</strong> {{ ipv4() ? 'IPv4 ' : '' }}{{ ipv6() ? 'IPv6 ' : '' }}{{ privateNetwork() ? 'private' : '' }}</good-paragraph>\n          <good-paragraph><strong>SSH keys:</strong> {{ selectedKeyIds().length }}</good-paragraph>\n          <good-paragraph><strong>Extras:</strong> {{ volumeEnabled() ? volumeSize() + ' GB volume · ' : '' }}{{ backups() ? 'backups · ' : '' }}{{ firewall() || 'no firewall' }}</good-paragraph>\n          <good-number-input label=\"Number of servers\" [showLabel]=\"true\" [min]=\"1\" [max]=\"5\" [(value)]=\"quantity\" />\n          <good-paragraph>Plan: {{ euro(selectedPlan().monthlyPrice) }} / month · IPv4: {{ euro(ipv4() ? 0.5 : 0) }} / month</good-paragraph>\n          @if (locationSurcharge()) { <good-paragraph>Location: {{ euro(locationSurcharge()) }} / month</good-paragraph> }\n          @if (volumeEnabled()) { <good-paragraph>Volume: {{ euro(volumePrice()) }} / month</good-paragraph> }\n          @if (backups()) { <good-paragraph>Backups: {{ euro(backupPrice()) }} / month</good-paragraph> }\n        </good-prose>\n    </good-assistant-body>\n    <good-assistant-footer>\n        <good-prose>\n          <good-subheading [level]=\"3\">{{ euro(totalPrice()) }} / month</good-subheading>\n          <good-paragraph>{{ euro(totalPrice() / 720) }} / hour estimated. Prices are illustrative and exclude tax.</good-paragraph>\n          @if (error()) { <good-alert tone=\"destructive\" title=\"Check your configuration\" [message]=\"error()\" /> }\n          <good-action-group orientation=\"responsive\">\n            <good-button (click)=\"create()\">Create {{ quantity() }} server{{ quantity() === 1 ? '' : 's' }}</good-button>\n            <good-button variant=\"outline\" (click)=\"cancel()\">Cancel</good-button>\n          </good-action-group>\n          <good-button variant=\"ghost\" size=\"small\" (click)=\"sourceOpen.set(true)\">View source</good-button>\n        </good-prose>\n    </good-assistant-footer>\n    <good-assistant-mobile>\n      <good-paragraph><strong>{{ selectedPlan().name }}</strong> · {{ location() }} · {{ quantity() }} server{{ quantity() === 1 ? '' : 's' }}</good-paragraph>\n      <good-subheading [level]=\"3\">{{ euro(totalPrice()) }} / month</good-subheading>\n      <good-button size=\"small\" (click)=\"create()\">Create {{ quantity() }} server{{ quantity() === 1 ? '' : 's' }}</good-button>\n    </good-assistant-mobile>\n  </good-assistant-panel>\n</good-main-view>\n\n<good-modal [(open)]=\"keyModalOpen\" size=\"default\">\n  <good-modal-header title=\"Add SSH public key\" description=\"This key is stored only in the current browser session.\" />\n  <good-group title=\"Key details\" appearance=\"plain\">\n    <good-input label=\"Key name\" [showLabel]=\"true\" placeholder=\"Work laptop\" [(value)]=\"keyName\" />\n    <good-textarea label=\"OpenSSH public key\" [showLabel]=\"true\" [rows]=\"4\"\n      placeholder=\"ssh-ed25519 AAAA...\" [(value)]=\"keyContent\" />\n    @if (keyError()) { <good-alert tone=\"destructive\" [message]=\"keyError()\" /> }\n  </good-group>\n  <good-modal-footer>\n    <good-action-group>\n      <good-button variant=\"outline\" (click)=\"keyModalOpen.set(false)\">Cancel</good-button>\n      <good-button (click)=\"addKey()\">Add key</good-button>\n    </good-action-group>\n  </good-modal-footer>\n</good-modal>\n\n<good-modal [(open)]=\"sourceOpen\" size=\"large\" [scrollBody]=\"true\">\n  <good-modal-header title=\"VPS configuration source\" />\n  <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"create-server-page.html\" />\n  <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"create-server-page.ts\" />\n  <good-code-block [code]=\"storeSource\" language=\"typescript\" title=\"vps-store.ts\" />\n</good-modal>\n";
export const vpsCreateTs = "import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';\nimport { Router } from '@angular/router';\nimport {\n  GoodActionGroupComponent, GoodAlertComponent, GoodButtonComponent, GoodCheckboxComponent,\n  GoodCodeBlockComponent, GoodExpandableComponent, GoodFormRowComponent, GoodGroupComponent, GoodInputComponent,\n  GoodHeadingComponent, GoodLinkComponent, GoodListboxComponent, GoodListboxItem, GoodMainViewComponent,\n  GoodModalComponent, GoodModalFooterComponent, GoodModalHeaderComponent, GoodNumberInputComponent,\n  GoodParagraphComponent, GoodProseComponent, GoodAssistantPanelComponent, GoodAssistantMainComponent,\n  GoodAssistantHeaderComponent, GoodAssistantBodyComponent, GoodAssistantFooterComponent, GoodAssistantMobileComponent,\n  GoodRadioGroupComponent, GoodRadioOption, GoodSectionComponent, GoodSelectComponent, GoodSelectOption, GoodSelectValue, GoodSubheadingComponent, GoodTableColumn,\n  GoodTableComponent, GoodTabComponent, GoodTabsComponent, GoodTextareaComponent,\n} from '@goodui/angular';\nimport { VPS_PLANS, VpsCaseStudyStore, VpsPlan } from './vps-store';\nimport { vpsCreateHtml, vpsCreateTs, vpsStoreTs } from './source-code.generated';\n\nconst imageVersions: Record<string, readonly string[]> = {\n  Ubuntu: ['26.04', '24.04', '22.04'], Fedora: ['44', '43'], Debian: ['13', '12'],\n  CentOS: ['Stream 10', 'Stream 9'], 'Rocky Linux': ['10', '9'], 'AlmaLinux': ['10', '9'],\n  'openSUSE': ['16', '15.6'], Docker: ['Ubuntu 24.04'],\n  WordPress: ['Ubuntu 24.04'], Nextcloud: ['Ubuntu 24.04'],\n};\n\n@Component({\n  selector: 'example-vps-create-server-page',\n  standalone: true,\n  imports: [GoodActionGroupComponent, GoodAlertComponent, GoodButtonComponent, GoodCheckboxComponent,\n    GoodCodeBlockComponent, GoodExpandableComponent, GoodFormRowComponent, GoodGroupComponent, GoodInputComponent,\n    GoodHeadingComponent, GoodLinkComponent, GoodListboxComponent, GoodMainViewComponent, GoodModalComponent,\n    GoodModalFooterComponent, GoodModalHeaderComponent, GoodNumberInputComponent,\n    GoodParagraphComponent, GoodProseComponent, GoodAssistantPanelComponent, GoodAssistantMainComponent,\n    GoodAssistantHeaderComponent, GoodAssistantBodyComponent, GoodAssistantFooterComponent, GoodAssistantMobileComponent,\n    GoodRadioGroupComponent, GoodSectionComponent, GoodSelectComponent, GoodSubheadingComponent, GoodTableComponent, GoodTabComponent,\n    GoodTabsComponent, GoodTextareaComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './create-server-page.html',\n})\nexport class VpsCreateServerPageComponent {\n  private readonly router = inject(Router);\n  private readonly store = inject(VpsCaseStudyStore);\n  readonly sourceOpen = signal(false);\n  readonly summaryOpen = signal(false);\n  readonly keyModalOpen = signal(false);\n  readonly keyName = signal('');\n  readonly keyContent = signal('');\n  readonly keyError = signal('');\n  readonly error = signal('');\n  readonly planId = signal<string | null>('cpx22');\n  readonly planCategory = signal<string | null>('regular');\n  readonly architecture = signal<string | null>('x86');\n  readonly architectureOptions: readonly GoodRadioOption[] = [\n    { value: 'x86', label: 'x86', description: 'Intel / AMD compatible' },\n    { value: 'arm64', label: 'Arm64', description: 'Arm-based processors' },\n  ];\n  readonly planCategories: readonly GoodRadioOption[] = [\n    { value: 'cost', label: 'Cost-optimized', description: 'Lower cost on established hardware' },\n    { value: 'regular', label: 'Regular performance', description: 'Balanced CPU and price' },\n  ];\n  readonly selectedPlan = computed(() => VPS_PLANS.find(plan => plan.id === this.planId()) ?? VPS_PLANS[2]);\n  readonly sharedPlans = computed(() => VPS_PLANS.filter(plan => plan.family === 'shared' && plan.category === this.planCategory()));\n  readonly dedicatedPlans = VPS_PLANS.filter(plan => plan.family === 'dedicated');\n  readonly planColumns: GoodTableColumn<VpsPlan>[] = [\n    { accessorKey: 'name', header: 'Type', enableSorting: true },\n    { accessorKey: 'vcpus', header: 'vCPUs', meta: { noWrap: true } },\n    { accessorKey: 'memoryGb', header: 'RAM (GB)', meta: { noWrap: true } },\n    { accessorKey: 'diskGb', header: 'SSD (GB)', meta: { noWrap: true } },\n    { accessorKey: 'trafficTb', header: 'Traffic (TB)', meta: { noWrap: true } },\n    { accessorKey: 'monthlyPrice', header: 'EUR / month', meta: { align: 'end', noWrap: true },\n      cell: context => this.euro(context.row.original.monthlyPrice) },\n  ];\n  readonly planRowId = (plan: VpsPlan): string => plan.id;\n  readonly location = signal<GoodSelectValue>('Helsinki');\n  readonly locations: readonly GoodSelectOption[] = [\n    { value: 'Nuremberg', label: '🇩🇪 Nuremberg', description: 'eu-central' },\n    { value: 'Falkenstein', label: '🇩🇪 Falkenstein', description: 'eu-central' },\n    { value: 'Helsinki', label: '🇫🇮 Helsinki', description: 'eu-central' },\n    { value: 'Singapore', label: '🇸🇬 Singapore', description: 'ap-southeast · +€7.00 / month' },\n    { value: 'Hillsboro', label: '🇺🇸 Hillsboro, OR', description: 'us-west' },\n    { value: 'Ashburn', label: '🇺🇸 Ashburn, VA', description: 'us-east' },\n  ];\n  readonly zone = computed(() => {\n    const location = String(this.location() ?? '');\n    if (location === 'Singapore') return 'ap-southeast';\n    if (location === 'Hillsboro') return 'us-west';\n    if (location === 'Ashburn') return 'us-east';\n    return 'eu-central';\n  });\n  readonly image = signal<GoodSelectValue>('Ubuntu');\n  readonly imageVersion = signal<GoodSelectValue>('26.04');\n  readonly osImages: readonly GoodSelectOption[] = ['Ubuntu', 'Fedora', 'Debian', 'CentOS', 'Rocky Linux', 'AlmaLinux', 'openSUSE']\n    .map(value => ({ value, label: value }));\n  readonly appImages: readonly GoodSelectOption[] = ['Docker', 'WordPress', 'Nextcloud']\n    .map(value => ({ value, label: value }));\n  readonly versionOptions = computed<readonly GoodSelectOption[]>(() =>\n    (imageVersions[String(this.image() ?? '')] ?? []).map(value => ({ value, label: value })));\n  readonly imageLabel = computed(() => `${String(this.image() ?? '')} ${String(this.imageVersion() ?? '')}`.trim());\n  readonly ipv4 = signal(true);\n  readonly ipv6 = signal(true);\n  readonly privateNetwork = signal(false);\n  readonly privateNetworkId = signal<GoodSelectValue>(null);\n  readonly privateNetworkOptions = computed<readonly GoodSelectOption[]>(() => {\n    const networks = [\n      { value: 'private-eu', label: 'Private network · Europe Central', zone: 'eu-central' },\n      { value: 'private-us-west', label: 'Private network · US West', zone: 'us-west' },\n      { value: 'private-us-east', label: 'Private network · US East', zone: 'us-east' },\n    ];\n    return networks.filter(network => network.zone === this.zone());\n  });\n  readonly sshKeys = signal<GoodListboxItem[]>([\n    { id: 'laptop', label: 'Laptop key', description: 'ed25519 · local demo' },\n  ]);\n  readonly selectedKeyIds = signal<readonly string[]>([]);\n  readonly volumeEnabled = signal(false);\n  readonly volumeName = signal('data');\n  readonly volumeSize = signal(20);\n  readonly firewall = signal<GoodSelectValue>(null);\n  readonly firewallOptions: readonly GoodSelectOption[] = [\n    { value: 'firewall-1', label: 'firewall-1', description: '10 example rules' },\n  ];\n  readonly backups = signal(false);\n  readonly placement = signal<GoodSelectValue>(null);\n  readonly placementOptions: readonly GoodSelectOption[] = [\n    { value: 'spread', label: 'Spread across hosts' }, { value: 'none', label: 'No placement group' },\n  ];\n  readonly labels = signal('');\n  readonly cloudConfig = signal('');\n  readonly quantity = signal(1);\n  readonly nameIndexes = computed(() => Array.from({ length: this.quantity() }, (_, index) => index));\n  readonly nameOverrides = signal<Record<number, string>>({});\n  readonly locationSurcharge = computed(() => this.location() === 'Singapore' ? 7 : 0);\n  readonly volumePrice = computed(() => this.volumeEnabled() ? this.volumeSize() * 0.05 : 0);\n  readonly backupPrice = computed(() => this.backups() ? this.selectedPlan().monthlyPrice * 0.2 : 0);\n  readonly unitPrice = computed(() => this.selectedPlan().monthlyPrice + (this.ipv4() ? 0.5 : 0)\n    + this.locationSurcharge() + this.volumePrice() + this.backupPrice());\n  readonly totalPrice = computed(() => this.unitPrice() * this.quantity());\n  readonly htmlSource = vpsCreateHtml;\n  readonly typescriptSource = vpsCreateTs;\n  readonly storeSource = vpsStoreTs;\n\n  euro(value: number): string { return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'EUR' }).format(value); }\n  selectFamily(id: string): void {\n    const current = this.selectedPlan();\n    if (current.family !== id) this.planId.set(id === 'shared' ? this.sharedPlans()[0]?.id ?? null : this.dedicatedPlans[0]?.id ?? null);\n  }\n  selectCategory(value: string | null): void {\n    if (value !== 'cost' && value !== 'regular') return;\n    this.planCategory.set(value);\n    this.planId.set(VPS_PLANS.find(plan => plan.family === 'shared' && plan.category === value)?.id ?? null);\n  }\n  selectImageFamily(id: string): void { this.setImage(id === 'apps' ? 'Docker' : 'Ubuntu'); }\n  setImage(value: GoodSelectValue): void {\n    const name = String(value ?? '');\n    this.image.set(name);\n    this.imageVersion.set(imageVersions[name]?.[0] ?? null);\n  }\n  nameFor(index: number): string {\n    const defaultName = `${String(this.image() ?? 'server').toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${this.selectedPlan().memoryGb}gb-${this.zone().replace(/[^a-z0-9]+/g, '-')}-${index + 1}`;\n    return this.nameOverrides()[index] ?? defaultName;\n  }\n  setName(index: number, value: string): void { this.nameOverrides.update(names => ({ ...names, [index]: value })); }\n  addKey(): void {\n    const name = this.keyName().trim();\n    const key = this.keyContent().trim();\n    if (!name || !/^ssh-(ed25519|rsa|ecdsa)\\s+\\S+/.test(key)) {\n      this.keyError.set('Enter a name and an OpenSSH public key.'); return;\n    }\n    const id = `key-${Date.now()}`;\n    this.sshKeys.update(keys => [...keys, { id, label: name, description: 'OpenSSH public key · local demo' }]);\n    this.selectedKeyIds.update(ids => [...ids, id]);\n    this.keyName.set(''); this.keyContent.set(''); this.keyError.set(''); this.keyModalOpen.set(false);\n  }\n  create(): void {\n    const names = Array.from({ length: this.quantity() }, (_, index) => this.nameFor(index).trim());\n    if (!this.planId() || !this.location() || !this.image() || !this.imageVersion()) {\n      this.showError('Choose a plan, location, image, and version.'); return;\n    }\n    if (!this.ipv4() && !this.ipv6() && !this.privateNetwork()) {\n      this.showError('Enable a public IP or a private network.'); return;\n    }\n    if (this.privateNetwork() && !this.privateNetworkOptions().some(option => option.value === this.privateNetworkId())) {\n      this.showError('Choose a private network or turn off private networking.'); return;\n    }\n    if (this.volumeEnabled() && !this.volumeName().trim()) {\n      this.showError('Give the volume a name or remove it.'); return;\n    }\n    if (names.some(name => !name || !/^[a-z0-9][a-z0-9-]*$/.test(name)) || new Set(names).size !== names.length) {\n      this.showError('Use distinct server names with lowercase letters, digits, and hyphens.'); return;\n    }\n    if (new TextEncoder().encode(this.cloudConfig()).length > 32 * 1024) {\n      this.showError('Cloud-init configuration must be 32 KiB or less.'); return;\n    }\n    this.error.set('');\n    const tags = this.labels().split(',').map(value => value.trim()).filter(Boolean);\n    const selectedKeys = this.sshKeys().filter(key => this.selectedKeyIds().includes(key.id)).map(key => key.label);\n    this.store.add(names.map(name => ({ name, plan: this.selectedPlan().name,\n      architecture: this.selectedPlan().category === 'cost' ? String(this.architecture()) : 'x86', image: this.imageLabel(),\n      location: String(this.location()), zone: this.zone(), labels: tags,\n      ipv4: this.ipv4(), ipv6: this.ipv6(), privateNetwork: this.privateNetwork() ? String(this.privateNetworkId()) : null,\n      sshKeys: selectedKeys, volume: this.volumeEnabled() ? { name: this.volumeName().trim(), sizeGb: this.volumeSize() } : null,\n      firewall: this.firewall() ? String(this.firewall()) : null, backups: this.backups(),\n      placement: this.placement() && this.placement() !== 'none' ? String(this.placement()) : null,\n      cloudConfig: this.cloudConfig(),\n    })));\n    void this.router.navigateByUrl('/examples/case-studies/vpshoster/servers');\n  }\n  cancel(): void { void this.router.navigateByUrl('/examples/case-studies/vpshoster/servers'); }\n  private showError(message: string): void { this.error.set(message); this.summaryOpen.set(true); }\n}\n";
export const vpsStoreTs = "import { Injectable, computed, signal } from '@angular/core';\n\nexport interface VpsPlan {\n  id: string;\n  family: 'shared' | 'dedicated';\n  category: 'cost' | 'regular' | 'general';\n  name: string;\n  vcpus: number;\n  memoryGb: number;\n  diskGb: number;\n  trafficTb: number;\n  monthlyPrice: number;\n}\n\nexport interface VpsServer {\n  id: string;\n  name: string;\n  plan: string;\n  architecture: string;\n  image: string;\n  location: string;\n  zone: string;\n  publicIp: string;\n  status: 'running' | 'stopped';\n  created: string;\n  labels: readonly string[];\n  ipv4: boolean;\n  ipv6: boolean;\n  privateNetwork: string | null;\n  sshKeys: readonly string[];\n  volume: { name: string; sizeGb: number } | null;\n  firewall: string | null;\n  backups: boolean;\n  placement: string | null;\n  cloudConfig: string;\n}\n\nexport const VPS_PLANS: readonly VpsPlan[] = [\n  { id: 'cx22', family: 'shared', category: 'cost', name: 'CX22', vcpus: 2, memoryGb: 4, diskGb: 40, trafficTb: 20, monthlyPrice: 11.49 },\n  { id: 'cx32', family: 'shared', category: 'cost', name: 'CX32', vcpus: 4, memoryGb: 8, diskGb: 80, trafficTb: 20, monthlyPrice: 21.49 },\n  { id: 'cpx22', family: 'shared', category: 'regular', name: 'CPX22', vcpus: 2, memoryGb: 4, diskGb: 80, trafficTb: 20, monthlyPrice: 19.49 },\n  { id: 'cpx32', family: 'shared', category: 'regular', name: 'CPX32', vcpus: 4, memoryGb: 8, diskGb: 160, trafficTb: 20, monthlyPrice: 35.49 },\n  { id: 'cpx42', family: 'shared', category: 'regular', name: 'CPX42', vcpus: 8, memoryGb: 16, diskGb: 320, trafficTb: 20, monthlyPrice: 69.49 },\n  { id: 'cpx52', family: 'shared', category: 'regular', name: 'CPX52', vcpus: 12, memoryGb: 24, diskGb: 480, trafficTb: 20, monthlyPrice: 100.49 },\n  { id: 'cpx62', family: 'shared', category: 'regular', name: 'CPX62', vcpus: 16, memoryGb: 32, diskGb: 640, trafficTb: 20, monthlyPrice: 129.99 },\n  { id: 'ccx23', family: 'dedicated', category: 'general', name: 'CCX23', vcpus: 4, memoryGb: 16, diskGb: 160, trafficTb: 20, monthlyPrice: 69.99 },\n  { id: 'ccx33', family: 'dedicated', category: 'general', name: 'CCX33', vcpus: 8, memoryGb: 32, diskGb: 240, trafficTb: 20, monthlyPrice: 129.99 },\n];\n\n@Injectable({ providedIn: 'root' })\nexport class VpsCaseStudyStore {\n  readonly notice = signal('');\n  readonly servers = signal<VpsServer[]>([\n    { id: 'sample-1', name: 'demo-node', plan: 'CPX22', architecture: 'x86', image: 'Ubuntu 26.04', location: 'Nuremberg',\n      zone: 'eu-central', publicIp: '192.0.2.10', status: 'running', created: '2026-10-01', labels: ['demo'],\n      ipv4: true, ipv6: true, privateNetwork: null, sshKeys: [], volume: null, firewall: null,\n      backups: false, placement: null, cloudConfig: '' },\n  ]);\n  readonly count = computed(() => this.servers().length);\n\n  add(servers: readonly Omit<VpsServer, 'id' | 'created' | 'publicIp' | 'status'>[]): void {\n    const start = this.servers().length + 1;\n    const created = new Date().toISOString().slice(0, 10);\n    this.servers.update(current => [...current, ...servers.map((server, index) => ({\n      ...server, id: `local-${Date.now()}-${index}`, created,\n      publicIp: server.ipv4 ? `192.0.2.${Math.min(254, start + index + 10)}`\n        : server.ipv6 ? `2001:db8::${start + index + 10}` : '—', status: 'running' as const,\n    }))]);\n    this.notice.set(`${servers.length} server${servers.length === 1 ? '' : 's'} added to the local demo.`);\n  }\n\n  setStatus(id: string, status: VpsServer['status']): void {\n    this.servers.update(servers => servers.map(server => server.id === id ? { ...server, status } : server));\n  }\n\n  remove(id: string): void {\n    this.servers.update(servers => servers.filter(server => server.id !== id));\n  }\n}\n";
